export type SentenceExercise = {
  english: string;
  target: string;
  words: string[];
  distractors: string[];
  hint: string;
  topic?: string;
  cefrLevel: string;
  language: "es" | "fr";
};

export type PickedSentence = SentenceExercise & { allWords: string[] };

function fisherYates<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j]!, a[i]!];
  }
  return a;
}

function levelKey(cefrLevel: string): string {
  const L = (cefrLevel || "A1").toUpperCase();
  if (L === "A1" || L === "A2" || L === "B1") return L;
  // B2+ reuse B1 pool
  return "B1";
}

