export function pickSentence(
  language: string,
  cefrLevel: string,
  topic?: string,
): PickedSentence {
  const level = levelKey(cefrLevel);
  const lang = language === "fr" ? "fr" : "es";
  let pool = EXERCISES.filter((e) => e.language === lang && e.cefrLevel === level);
  if (topic) {
    const topical = pool.filter((e) => e.topic === topic);
    if (topical.length) pool = topical;
  }
  if (!pool.length) {
    pool = EXERCISES.filter((e) => e.language === lang);
  }
  const exercise = pool[Math.floor(Math.random() * pool.length)]!;
  return {
    ...exercise,
    allWords: fisherYates([...exercise.words, ...exercise.distractors]),
  };
}

export function listSentenceTopics(): string[] {
  return ["Daily Life", "Travel", "Food", "Animals", "Work", "Family", "Sports", "Nature"];
}
